// Тема kharkiv/heat/<id>/telemetry → id ІТП
const station = msg.topic.split("/")[2];
const d = msg.payload;     // mqtt in уже розібрав JSON
// Формула (5'): значення — число в допустимому діапазоні
const ok = (v, lo, hi) =>
    typeof v === "number" && v >= lo && v <= hi;
const errors = [];
if (!ok(d.t_sup, 30, 110)) errors.push("t_sup");
if (!ok(d.t_ret, 20, 80)) errors.push("t_ret");
if (!ok(d.g, 0, 50)) errors.push("g");
if (!ok(d.t_out, -40, 50)) errors.push("t_out");
if (!Number.isInteger(d.ts)) errors.push("ts");
// Узгодженість: зворотна вода не може бути гарячішою за подачу
if (errors.length === 0 && d.t_ret > d.t_sup) errors.push("t_ret>t_sup");

if (errors.length > 0) {
    const n = (context.get("rejected") || 0) + 1;
    context.set("rejected", n);
    node.status({ fill: "red", shape: "dot",
                  text: `відхилено: ${n}` });
    msg.payload = { station, errors, raw: d };
    return [null, msg];    // вихід 2 — відхилені
}
msg.station = station;
msg.ts = d.ts;
msg.payload = { t_sup: d.t_sup, t_ret: d.t_ret, g: d.g, t_out: d.t_out };
return [msg, null];        // вихід 1 — коректні

// Формула (В2): теплова потужність ІТП, кВт
// 1,163 кВт·год/(м³·К) — теплоємність одиниці об'єму води
function heatPower(g, tSup, tRet) {
    return 1.163 * g * (tSup - tRet);
}

const ALPHA = 0.2;   // коефіцієнт згладжування
const ON = 20.0;     // поріг увімкнення тривоги: Q_ema ≤ 20 кВт
const OFF = 40.0;    // поріг вимкнення тривоги: Q_ema ≥ 40 кВт
const G_PUMP = 0.5;  // G нижче — циркуляції немає (насос стоїть)

// Стан кожного ІТП зберігаємо в контексті вузла
const key = "st_" + msg.station;
const st = context.get(key) || { ema: null, gema: null, alarm: 0, cause: 0 };
const p = msg.payload;
const q = heatPower(p.g, p.t_sup, p.t_ret);
// Формула (8): експоненційне згладжування Q і G
st.ema = st.ema === null ? q : ALPHA * q + (1 - ALPHA) * st.ema;
st.gema = st.gema === null ? p.g : ALPHA * p.g + (1 - ALPHA) * st.gema;
// Формула (9'): тривога з гістерезисом — на падіння потужності
const before = { alarm: st.alarm, cause: st.cause };
if (st.alarm === 0 && st.ema <= ON) st.alarm = 1;
if (st.alarm === 1 && st.ema >= OFF) st.alarm = 0;
// Правило двох величин: причину тривоги визначає витрата G.
// 1 — зупинка насоса (циркуляції немає, G < 0,5 м³/год),
// 2 — низьке теплоспоживання (Q мала, але G у нормі: тепла погода).
// Береться поточний вимір G: насос зупиняється за секунди, а EMA
// запізнюється. Причина 1 «прилипає» до кінця епізоду тривоги.
if (st.alarm === 0) st.cause = 0;
else if (st.cause !== 1) st.cause = p.g < G_PUMP ? 1 : 2;
context.set(key, st);

p.q = Math.round(q * 10) / 10;
p.q_ema = Math.round(st.ema * 10) / 10;
p.g_ema = Math.round(st.gema * 100) / 100;
p.alarm = st.alarm;
p.cause = st.cause;

let alarmMsg = null;      // лише при зміні стану або причини
if (st.alarm !== before.alarm || st.cause !== before.cause) {
    alarmMsg = {
        topic: `kharkiv/heat/${msg.station}/alarm`,
        payload: JSON.stringify({
            ts: msg.ts,
            alarm: st.alarm,
            cause: st.cause,
            q_ema: p.q_ema,
            g_ema: p.g_ema,
        }),
    };
}
return [msg, alarmMsg];

// Параметри запиту INSERT у вузлі «PostgreSQL: виміри»
// (у запиті вони позначені $1, $2, … $12)
const p = msg.payload;
msg.params = [
    msg.ts,                 // $1 — час виміру, мс від 1970 р.
    msg.station,            // $2 — ІТП
    p.t_sup, p.t_ret,       // $3, $4
    p.g, p.t_out,           // $5, $6
    p.q, p.q_ema, p.g_ema,  // $7, $8, $9
    p.alarm, p.cause,       // $10, $11
    Date.now() - msg.ts,    // $12 — затримка, формула (10)
];
return msg;

// Тема kharkiv/heat/<id>/status, вміст online|offline
const station = msg.topic.split("/")[2];
const online = msg.payload === "online" ? 1 : 0;
msg.params = [station, online];   // $1, $2 у запиті
return msg;

// Вимір, який не вдалося записати, зберігаємо в черзі
// контексту потоку, щоб записати пізніше (патерн «зберегти–переслати»)
const MAX = 50000;          // ≈ 7 год потоку трьох ІТП
const q = flow.get("buffer") || [];
if (q.length < MAX) q.push(msg.params);
flow.set("buffer", q);
node.status({ fill: q.length ? "yellow" : "green", shape: "dot",
              text: `у буфері: ${q.length}` });
return null;

// Беремо з черги до 100 вимірів і повторно надсилаємо у вузол запису.
// Якщо база ще недоступна, вузол catch знову поверне їх у буфер.
// Повторна вставка безпечна: ON CONFLICT (station, ts) DO NOTHING.
const q = flow.get("buffer") || [];
if (q.length === 0) {
    node.status({ fill: "green", shape: "dot", text: "буфер порожній" });
    return null;
}
const batch = q.splice(0, 100);
flow.set("buffer", q);
node.status({ fill: "yellow", shape: "dot",
              text: `надіслано ${batch.length}, лишилось ${q.length}` });
// $12 — затримка перераховується: вимір чекав у буфері
return [batch.map(params => {
    params[11] = Date.now() - params[0];
    return { params, resent: true };
})];
